INSERT INTO knowledge_documents (title, content, source, category, tags, isActive, createdAt, updatedAt) 
VALUES 
('شروط الموقوف - الفقه الإسلامي', 'يشترط في الموقوف أن يكون مالاً متقوماً يمكن الانتفاع به مع بقاء عينه، كالعقار والحيوان والكتب.', 'الفقه الإسلامي العام', 'jurisprudence', 'شروط الموقوف، المال المتقوم، الانتفاع', 1, FROM_UNIXTIME(1767919573), FROM_UNIXTIME(1767919573)),
('الوقف على النفس - الخلاف الفقهي', 'اختلف الفقهاء في جواز الوقف على النفس، فأجازه الحنفية والحنابلة، ومنعه المالكية والشافعية.', 'الفقه المقارن - الوقف', 'jurisprudence', 'الوقف على النفس، الخلاف الفقهي، المذاهب', 1, FROM_UNIXTIME(1767919573), FROM_UNIXTIME(1767919573)),
('نظارة الوقف - الشروط والأحكام', 'للواقف أن يشترط النظارة لنفسه أو لغيره، وللناظر أن يتقاضى أجرة على عمله بقدر المعروف إن لم يشترط الواقف.', 'الفقه الإسلامي - أحكام الوقف', 'jurisprudence', 'نظارة الوقف، الناظر، الأجرة', 1, FROM_UNIXTIME(1767919573), FROM_UNIXTIME(1767919573)),
('شرط الواقف - الالتزام به', 'شرط الواقف كنص الشارع في اللزوم، فيجب الالتزام بشروط الواقف ما لم تخالف الشرع.', 'القواعد الفقهية - الوقف', 'jurisprudence', 'شرط الواقف، الالتزام، الشرع', 1, FROM_UNIXTIME(1767919573), FROM_UNIXTIME(1767919573)),
('الوقف المؤقت - حكمه', 'اختلف الفقهاء في جواز الوقف المؤقت، فأجازه المالكية ومنعه الجمهور، واشترطوا التأبيد في الوقف.', 'الفقه المقارن - الوقف', 'jurisprudence', 'الوقف المؤقت، التأبيد، الخلاف', 1, FROM_UNIXTIME(1767919573), FROM_UNIXTIME(1767919573)),
('الوقف على غير المسلمين - الحكم', 'يجوز الوقف على غير المسلمين في أمور البر كالفقراء والمرضى، ولا يجوز على الكنائس والبيع.', 'الفقه الإسلامي - أحكام الوقف', 'jurisprudence', 'الوقف على غير المسلمين، البر، الجواز', 1, FROM_UNIXTIME(1767919573), FROM_UNIXTIME(1767919573)),
('إحياء الوقف المتعطل - الأحكام', 'إذا تعطل الوقف وخرب، فللناظر أو القاضي إحياؤه وتعميره من ريع الوقف أو من بيت المال إن لم يكن للوقف ريع.', 'الفقه الإسلامي - إدارة الأوقاف', 'jurisprudence', 'إحياء الوقف، التعمير، الناظر', 1, FROM_UNIXTIME(1767919573), FROM_UNIXTIME(1767919573)),
('الوقف الأهلي - التعريف والأحكام', 'الوقف الأهلي هو ما وقف على الذرية والأقارب ثم على جهة بر، وله أحكام خاصة في الإدارة والتوزيع.', 'الفقه الإسلامي - أنواع الوقف', 'jurisprudence', 'الوقف الأهلي، الذرية، الأقارب', 1, FROM_UNIXTIME(1767919573), FROM_UNIXTIME(1767919573)),
('الوقف المشترك - الأحكام', 'يجوز أن يشترك أكثر من واحد في وقف عين واحدة، ولكل منهم نصيبه في الثواب والأجر.', 'الفقه الإسلامي - أحكام الوقف', 'jurisprudence', 'الوقف المشترك، الاشتراك، النصيب', 1, FROM_UNIXTIME(1767919573), FROM_UNIXTIME(1767919573)),
('الوقف على المساجد - الفضل والأحكام', 'الوقف على المساجد من أفضل أنواع الوقف، ويشمل بناء المساجد والإنفاق على صيانتها وخدمتها.', 'الفقه الإسلامي - فضائل الوقف', 'jurisprudence', 'الوقف على المساجد، الفضل، البناء', 1, FROM_UNIXTIME(1767919573), FROM_UNIXTIME(1767919573));